import { fileURLToPath } from 'node:url';
import { configDefaults, defineConfig } from 'vitest/config';

export default defineConfig({
  resolve: {
    // Mirrors WXT's own "@" -> project root alias (see .wxt/tsconfig.json,
    // generated by `wxt prepare`) - without this, Vitest can't load
    // entrypoints/*.ts or components/lookup-popup.ts, which both import
    // shared code via "@/utils/...". WXT's build (Vite) resolves this on
    // its own; Vitest needs its own config since it doesn't go through WXT.
    alias: {
      '@': fileURLToPath(new URL('.', import.meta.url)),
    },
  },
  test: {
    // .claude/worktrees/ holds nested checkouts for background agent tasks;
    // without this, their copies of this repo's own *.test.ts files get
    // picked up too, double-counting (and double-running) every test.
    // Spread Vitest's own defaults (node_modules, dist, .git, ...) rather
    // than replacing them outright.
    exclude: [...configDefaults.exclude, '**/.claude/worktrees/**'],
  },
});
